/**
 * Bulk imports workout videos from a folder using the CSV generated by
 * scripts/scan-workouts.ts.
 *
 * For each CSV row:
 *   1. Creates a Mux direct upload.
 *   2. Streams the local video file to the Mux upload URL.
 *   3. Inserts a workout record with muxAssetId = Mux upload id
 *      (the Mux webhook will swap in the real asset id + playback id
 *      once encoding completes).
 *
 * Usage:
 *   npx tsx scripts/bulk-import-workouts.ts [folder-path]
 */
import { config } from "dotenv";
config({ path: ".env.local" });
import fs from "fs";
import path from "path";
import os from "os";
import { parse } from "csv-parse/sync";
import { db, workouts } from "@/lib/db";
import { createDirectUpload } from "@/lib/mux";
import { slugify } from "@/lib/utils";

type Row = {
  filename: string;
  title: string;
  description: string;
  durationMin: string;
  intensity: string;
  bodyFocus: string;
  instructor: string;
  usesHoop: string;
};

async function uploadFile(localPath: string, uploadUrl: string): Promise<void> {
  const stat = fs.statSync(localPath);
  const stream = fs.createReadStream(localPath);

  // Node fetch supports streams for PUT bodies since v18, but the Node
  // types don't model the `duplex` field and stream bodies yet.
  const res = await fetch(uploadUrl, {
    method: "PUT",
    body: stream as unknown as BodyInit,
    headers: {
      "Content-Type": "application/octet-stream",
      "Content-Length": String(stat.size),
    },
    // @ts-expect-error — runtime supports duplex, types don't yet
    duplex: "half",
  });

  if (!res.ok) {
    throw new Error(`Upload failed: HTTP ${res.status} ${await res.text()}`);
  }
}

async function main() {
  const folder = process.argv[2]
    ? path.resolve(process.argv[2])
    : path.join(os.homedir(), "Desktop", "infinity-hoop-workouts");

  const csvPath = path.join(folder, "_import.csv");
  if (!fs.existsSync(csvPath)) {
    console.error(`❌ CSV not found: ${csvPath}`);
    console.error(`   Run 'npx tsx scripts/scan-workouts.ts' first.`);
    process.exit(1);
  }

  const rows = parse(fs.readFileSync(csvPath, "utf8"), {
    columns: true,
    skip_empty_lines: true,
    trim: true,
  }) as Row[];

  console.log(`Importing ${rows.length} workout(s)...\n`);

  let ok = 0;
  let fail = 0;

  for (const [i, row] of rows.entries()) {
    const filePath = path.join(folder, row.filename);
    if (!fs.existsSync(filePath)) {
      console.error(`[${i + 1}/${rows.length}] ❌ Missing file: ${row.filename}`);
      fail++;
      continue;
    }

    const mb = (fs.statSync(filePath).size / (1024 * 1024)).toFixed(1);
    process.stdout.write(`[${i + 1}/${rows.length}] ${row.title}  (${mb} MB)… `);

    try {
      const upload = await createDirectUpload({
        corsOrigin: process.env.NEXT_PUBLIC_APP_URL ?? "*",
      });

      await uploadFile(filePath, upload.url);

      const slug = slugify(row.title) + "-" + Math.random().toString(36).slice(2, 6);
      const bodyFocus = row.bodyFocus.split("|").map((s) => s.trim()).filter(Boolean);

      await db.insert(workouts).values({
        slug,
        title: row.title,
        description: row.description || null,
        instructor: row.instructor || null,
        durationMin: parseInt(row.durationMin, 10) || 25,
        intensity: (["beginner", "intermediate", "advanced"].includes(row.intensity)
          ? row.intensity
          : "intermediate") as "beginner" | "intermediate" | "advanced",
        bodyFocus,
        equipment: ["hoop"],
        usesHoop: row.usesHoop?.toLowerCase() !== "false",
        muxAssetId: upload.id,
        muxPlaybackId: null,
        publishedAt: new Date(),
        sortOrder: i,
      });

      console.log("✓");
      ok++;
    } catch (err) {
      console.log("✗");
      console.error(`      ${(err as Error).message}`);
      fail++;
    }
  }

  console.log(`\n✅ Done. Imported: ${ok}  Failed: ${fail}`);
  console.log(
    `\nMux is now encoding ${ok} video(s) in the background. They'll\nappear on the /workouts page automatically as each one finishes\n(usually 1-3 minutes per video).`
  );
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => process.exit(0));
